// Parse order text from WhatsApp message
const messageText = $input.item.json.message?.text || '';
const fromPhone = $input.item.json.from?.phone || '';

// Order pattern: "2m red chiffon, Jane, +254700456789"
// Extract: quantity, product, customer_name, customer_phone
const patterns = [
  /(\d+)\s*(?:m|meter|metre|senti)\s+(.+?)\s*,\s*(.+?)\s*,\s*(\+?254\d{9})/i,
  /(\d+)\s*(?:m|meter|metre|senti)\s+(.+?)\s+for\s+(.+?)\s+(\+?254\d{9})/i
];

let orderData = {
  quantity: null,
  product_name: '',
  customer_name: '',
  customer_phone: fromPhone, // Default to sender if not in message
  raw_text: messageText
};

for (const pattern of patterns) {
  const match = messageText.match(pattern);
  if (match) {
    orderData.quantity = parseInt(match[1]);
    orderData.product_name = match[2].trim();
    orderData.customer_name = match[3].trim();
    if (match[4]) orderData.customer_phone = match[4];
    break;
  }
}

// If parsing failed, use simple split
if (!orderData.quantity && messageText) {
  const parts = messageText.split(',').map(p => p.trim());
  if (parts.length >= 2) {
    // Try to extract quantity from first part
    const qtyMatch = parts[0].match(/(\d+)/);
    if (qtyMatch) {
      orderData.quantity = parseInt(qtyMatch[1]);
      orderData.product_name = parts[0].replace(/\d+/, '').trim();
    }
    orderData.customer_name = parts[1] || '';
    if (parts[2]) orderData.customer_phone = parts[2];
  }
}

return {
  json: {
    ...orderData,
    message_id: $input.item.json.message?.id || '',
    timestamp: new Date().toISOString()
  }
};

// Generate order ID (format: O001, O002, etc.)
const timestamp = new Date().getTime();
const random = Math.floor(Math.random() * 1000);
const orderId = `O${timestamp.toString().slice(-6)}${random.toString().padStart(3, '0')}`;

return {
  json: {
    order_id: orderId,
    ...$input.item.json
  }
};
